<script>
const $=s=>document.querySelector(s);
const hoy=()=>{const d=new Date();$('#fecha').valueAsDate=new Date(d.getTime()-d.getTimezoneOffset()*6e4);$('#hora').value=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};
hoy();
const cajas=()=>[...document.querySelectorAll('input[name=p]')];
// Puntos de cada fase: todos se pueden marcar, modificar y eliminar
const DEF={"1": ["Se realizó la inspección física del generador (niveles de diésel, aceite, refrigerante y ausencia de fugas).", "Se verificó que los bancos de baterías de las UPS reporten estar al 100% de capacidad de carga antes del corte.", "Se desenergizó la acometida principal de Coopeguanacaste (apertura del interruptor / breaker general).", "El ATS realizó la transferencia de carga y el generador eléctrico arrancó correctamente de forma automática."], "2": ["Se desactivó el Aire Acondicionado de Precisión (PAC) principal de forma manual.", "Se comprobó mediante el BMS y físicamente el encendido automático del A/C de confort de contingencia.", "Se simuló el apagado del PAC en el microdatacenter, verificando la apertura automática de sus puertas.", "Se colocó en OFF el A/C N° 1 (ECOLD) del cuarto de UPS y se validó el encendido automático del A/C N° 2 (Innovar).", "Se validó que el equipo de aire acondicionado marca CIAC se apagara de manera automática."], "3": ["Se restableció la energía comercial; se confirmó el ciclo de enfriamiento y apagado del generador eléctrico.", "Se comprobó que el PAC principal del centro de datos reiniciara exitosamente tras la restitución del flujo eléctrico.", "Se devolvieron los equipos a estado normal (ECOLD encendido, Innovar apagado, puertas cerradas).", "Se verificó en el BMS que los parámetros están estabilizados y el panel libre de alarmas o advertencias."]};
function crecer(t){t.style.height='auto';t.style.height=t.scrollHeight+'px'}
function agregarPunto(sec,texto='',ok=false){
  const ch=document.querySelector('.chk[data-sec="'+sec+'"]');
  const d=document.createElement('div');d.className='it extra';
  d.innerHTML='<label class="ck" title="Marcar como verificado"><input type="checkbox" name="p"><span class="box" aria-hidden="true"></span></label>'
    +'<textarea class="txt" rows="1" maxlength="300" placeholder="Describa el punto verificado" aria-label="Descripción del punto"></textarea><span class="prt" aria-hidden="true"></span>'
    +'<button type="button" class="rm" title="Eliminar este punto" aria-label="Eliminar este punto">&#x2715;</button>';
  const t=d.querySelector('.txt'),pr=d.querySelector('.prt');t.value=texto;pr.textContent=texto;t.addEventListener('input',()=>{crecer(t);pr.textContent=t.value});
  t.addEventListener('keydown',e=>{if(e.key==='Enter')e.preventDefault()});
  const c=d.querySelector('input[name=p]');c.checked=ok;c.addEventListener('change',avance);
  d.querySelector('.rm').onclick=()=>{
    if(ch.querySelectorAll('.it').length<=1){$('#msg').textContent='Cada fase debe tener al menos un punto.';return}
    const v=t.value.trim();if(v&&!confirm('¿Eliminar este punto?\n\n«'+v+'»'))return;d.remove();avance()};
  ch.appendChild(d);requestAnimationFrame(()=>crecer(t));avance();return d}
function cargarPredeterminados(){document.querySelectorAll('.chk').forEach(ch=>{ch.innerHTML='';DEF[ch.dataset.sec].forEach(x=>agregarPunto(ch.dataset.sec,x))})}
document.querySelectorAll('.addp').forEach(b=>b.onclick=()=>agregarPunto(b.dataset.sec).querySelector('.txt').focus());
addEventListener('resize',()=>document.querySelectorAll('.it.extra .txt').forEach(crecer));
const quitarExtras=()=>document.querySelectorAll('.it.extra').forEach(e=>e.remove());
cargarPredeterminados();
// Avance por sección y total
function avance(){
  const TOTAL=cajas().length;
  document.querySelectorAll('.chk').forEach(ch=>{const c=[...ch.querySelectorAll('input[name=p]')],m=c.filter(i=>i.checked).length;
    const p=ch.previousElementSibling.querySelector('[data-prog]');p.textContent=m+' / '+c.length;p.classList.toggle('ok',m===c.length)});
  const m=cajas().filter(i=>i.checked).length,r=$('#resumen');
  r.textContent=m===TOTAL?'✓ Los '+TOTAL+' puntos del simulacro fueron verificados.':m+' de '+TOTAL+' puntos verificados · faltan '+(TOTAL-m)+(m?'. Si alguno no se cumplió, explíquelo en Observaciones.':'.');
  r.className='resumen '+(m===TOTAL?'ok':'');
}
avance();

// Firma digital
const pads={};
function pad(id){const c=document.getElementById(id),x=c.getContext('2d');let d=false,has=false;
  function size(){const r=c.getBoundingClientRect(),k=devicePixelRatio||1;c.width=r.width*k;c.height=r.height*k;x.scale(k,k);x.lineWidth=2.2;x.lineCap='round';x.lineJoin='round';x.strokeStyle='#0b2a4a'}
  size();
  const pt=e=>{const r=c.getBoundingClientRect();return[e.clientX-r.left,e.clientY-r.top]};
  c.onpointerdown=e=>{d=true;c.setPointerCapture(e.pointerId);x.beginPath();x.moveTo(...pt(e))};
  c.onpointermove=e=>{if(!d)return;x.lineTo(...pt(e));x.stroke();has=true};
  c.onpointerup=c.onpointercancel=()=>{d=false};
  pads[id]={clear(){x.clearRect(0,0,c.width,c.height);has=false},has:()=>has,data:()=>c.toDataURL('image/png'),load(u){const i=new Image();i.onload=()=>{const r=c.getBoundingClientRect();x.clearRect(0,0,r.width,r.height);x.drawImage(i,0,0,r.width,r.height);has=true};i.src=u},url:()=>{const t=document.createElement('canvas');t.width=c.width;t.height=c.height;const y=t.getContext('2d');y.fillStyle='#fff';y.fillRect(0,0,t.width,t.height);y.filter='invert(0)';y.drawImage(c,0,0);
    const im=y.getImageData(0,0,t.width,t.height);return t.toDataURL('image/png')},canvas:c}}
pad('c1');
document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>pads[b.dataset.clear].clear());

function reset(){$('#f').reset();cargarPredeterminados();hoy();pads.c1.clear();$('#msg').textContent='';$('#e1').textContent='';
  document.querySelectorAll('#f input,#f textarea').forEach(el=>el.style.borderColor='');avance();editando=null;franjaEdicion($('#f'),'',reset)}
$('#rst').onclick=()=>{if(confirm('¿Borrar todos los datos de la bitácora?'))reset()};

function botonImprimir(){if(!$('#pr')){const p=document.createElement('button');p.id='pr';p.type='button';p.textContent='Imprimir / guardar PDF';p.onclick=()=>print();$('.bar').appendChild(p)}}
$('#fin').onclick=()=>{
  const errs=[],miss=[];
  ['fecha','hora','tec','firmante'].forEach(id=>{const el=$('#'+id),bad=!el.value.trim();el.style.borderColor=bad?'var(--err)':'';if(bad)miss.push(id)});
  if(miss.length)errs.push('Complete los campos obligatorios (*).');
  const vacios=[...document.querySelectorAll('.it.extra .txt')].filter(t=>{const bad=!t.value.trim();t.style.borderColor=bad?'var(--err)':'';return bad});
  if(vacios.length)errs.push('Hay puntos sin descripción: escríbala o elimine la línea.');
  const faltan=cajas().filter(i=>!i.checked).length;
  const obs=$('#obs');obs.style.borderColor='';
  if(faltan&&!obs.value.trim()){obs.style.borderColor='var(--err)';errs.push('Hay '+faltan+' punto(s) sin marcar: explique el motivo en Observaciones y contingencias.')}
  $('#e1').textContent=pads.c1.has()?'':'Falta la firma.';
  if(!pads.c1.has())errs.push('La firma del técnico es obligatoria.');
  $('#msg').style.color='';$('#msg').textContent=errs.join(' ');
  if(errs.length)return;
  const o=collect();const antes=editando;
  if(!antes||antes!==o.id){if(lista.some(a=>a.id===o.id)&&!confirm('Ya existe una bitácora del '+o.fecha.split('-').reverse().join('/')+' '+o.hora+'. ¿Reemplazarla?'))return}
  $('#fin').disabled=true;
  REG.guardar(o.id,o,{original:antes||'',reemplazar:true}).then(()=>{editando=o.id;
    $('#msg').style.color='var(--ink)';$('#msg').textContent='Bitácora del '+o.fecha.split('-').reverse().join('/')+' '+o.hora+(antes?' actualizada':' guardada')+' en el servidor. Use «Imprimir / guardar PDF» para conservarla.';
    franjaEdicion($('#f'),'Editando la bitácora del '+o.fecha.split('-').reverse().join('/')+' '+o.hora+'. Si vuelve a finalizar, se actualiza este registro.',reset);refresh();
    avisoExito({titulo:antes?'Bitácora actualizada':'Bitácora finalizada y guardada',texto:'La bitácora del '+o.fecha.split('-').reverse().join('/')+' '+o.hora+(o.tec?' ('+o.tec+')':'')+(antes?' se actualizó':' quedó guardada')+' en el servidor; se puede consultar desde cualquier computadora.\nPara conservarla de forma oficial, imprímala o guárdela en PDF.',botones:[{t:'Imprimir / guardar PDF',p:true,f:()=>print()},{t:'Llenar una nueva',f:()=>reset()},{t:'Cerrar'}]})})
  .catch(e=>{$('#msg').textContent='Bitácora firmada, pero no se pudo guardar en el servidor: '+e.message+' Guárdela en PDF o intente de nuevo.'})
  .finally(()=>{$('#fin').disabled=false});
  botonImprimir();
};

const LS='bitacoras_simulacro_v1',REG=Registro('bitacora');
let editando=null,lista=[];
function collect(){const o={fecha:$('#fecha').value,hora:$('#hora').value,tec:$('#tec').value.trim(),firmante:$('#firmante').value.trim(),obs:$('#obs').value.trim(),
  items:[...document.querySelectorAll('.it.extra')].map(d=>({s:+d.closest('.chk').dataset.sec,t:d.querySelector('.txt').value.trim(),ok:d.querySelector('input[name=p]').checked})),
  f1:pads.c1.data(),at:new Date().toISOString()};
  o.total=cajas().length;o.hechos=cajas().filter(i=>i.checked).length;o.id=o.fecha+' '+o.hora;return o}
function abrir(a){$('#msg').textContent='';$('#fecha').value=a.fecha;$('#hora').value=a.hora;$('#tec').value=a.tec||'';$('#firmante').value=a.firmante||'';$('#obs').value=a.obs||'';
  quitarExtras();
  if(a.items)a.items.forEach(x=>agregarPunto(x.s,x.t,x.ok));
  else{let n=0;['1','2','3'].forEach(k=>DEF[k].forEach(x=>{n++;agregarPunto(k,x,(a.p||[]).includes(n))}));(a.extras||[]).forEach(x=>agregarPunto(x.s,x.t,x.ok))} // bitácoras guardadas con la versión anterior
  avance();pads.c1.clear();pads.c1.load(a.f1);botonImprimir();scrollTo({top:0,behavior:'smooth'})}
const panel={REG,etiqueta:'bitácora',lista:()=>lista,editando:()=>editando,
  titulo:a=>(a.fecha||'').split('-').reverse().join('/')+' '+(a.hora||''),
  detalle:a=>{const n=a.hechos??(a.p||[]).length,tot=a.total||13;return [a.tec,n+'/'+tot+' puntos'+(n<tot?' (con observaciones)':''),'registró '+a._r.creado_por+(a._r.modificado_por?' · editó '+a._r.modificado_por:'')].filter(Boolean).join(' · ')},
  abrir:async id=>{const r=await REG.ver(id);abrir(r.datos);editando=r.id;
    franjaEdicion($('#f'),'Editando la bitácora del '+panel.titulo(r.datos)+'. Haga los cambios y pulse «Finalizar y generar bitácora» para actualizarla.',reset)},
  despues:async id=>{if(editando===id)reset();refresh()}};
async function refresh(){try{lista=(await REG.lista()).map(r=>({...r.datos,id:r.id,_r:r})).sort((x,y)=>String(y.id).localeCompare(String(x.id)))}
  catch(e){$('#reg').hidden=false;$('#lst').textContent='No se pudo cargar el registro del servidor: '+e.message;return}
  panelRegistros(panel)}
(async()=>{try{const n=await REG.migrar(LS,(k,v)=>v.id||k);if(n){$('#msg').style.color='var(--ink)';$('#msg').textContent='Se subieron al servidor '+n+' bitácora(s) que estaban guardadas solo en este navegador.'}}catch(e){}refresh()})();
</script>
